//! Validated project compilation shared by worker hosts, without editor state.

use rspice_design::project_sources::{
    MAX_PROJECT_SOURCE_LOGICAL_PATH_BYTES, ProjectSourceBundle, ProjectSourceError,
    ProjectSourceLanguage,
};
use rspice_veriloga::RuntimeCompileReport;

use super::{ProjectVerilogACompileError, build_profile, compile_project_bundle_source};

/// Verified secondary-module payload transferred only inside the browser
/// worker. Generated bytes never become project/editor state.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub struct WasmJitWorkerArtifact {
    pub abi_version: u32,
    pub emitter_version: u32,
    pub cache_key: String,
    pub digest: String,
    pub module_bytes: Vec<u8>,
    pub value_exports: Vec<String>,
    /// The module assignment pass, when it has steps to run. A module whose
    /// pass is empty exports no kernel for it, so the absence has to survive
    /// the wire: the worker then runs no assignment step, which is exactly
    /// what the native executable does.
    pub assignment_export: Option<String>,
    pub post_assignment_export: Option<String>,
    /// Whole-model drivers. Present only when the model is eligible to fuse;
    /// the worker keeps the per-entry table either way.
    #[serde(default)]
    pub evaluation_kernel_export: Option<String>,
    #[serde(default)]
    pub stamp_kernel_export: Option<String>,
}

/// Available to a host test as well as to the worker build, so the wire shape
/// of an artifact can be pinned without a browser.
#[cfg(feature = "wasm-jit")]
impl WasmJitWorkerArtifact {
    pub fn from_compiled(artifact: &rspice_veriloga::wasm_jit::WasmJitModelArtifact) -> Self {
        Self {
            abi_version: artifact.module().abi_version(),
            emitter_version: artifact.module().emitter_version(),
            cache_key: artifact.cache_key().to_owned(),
            digest: artifact.module().digest().to_owned(),
            module_bytes: artifact.module().bytes().to_vec(),
            value_exports: artifact
                .entries()
                .iter()
                .map(|entry| entry.export_name().to_owned())
                .collect(),
            assignment_export: artifact.assignment_export().map(str::to_owned),
            post_assignment_export: artifact.post_assignment_export().map(str::to_owned),
            evaluation_kernel_export: artifact.evaluation_kernel_export().map(str::to_owned),
            stamp_kernel_export: artifact.stamp_kernel_export().map(str::to_owned),
        }
    }
}

/// Source admission failures, distinct from diagnosed compiler failures.
#[derive(Debug)]
pub enum WorkerCompileRequestError {
    Language,
    SourceBundle(ProjectSourceError),
    BuildProfile(String),
    ModuleSelection,
}

impl std::fmt::Display for WorkerCompileRequestError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Language => {
                formatter.write_str("Verilog-A worker received a non-Verilog-A source bundle.")
            }
            Self::SourceBundle(error) => {
                write!(
                    formatter,
                    "Verilog-A worker source bundle is invalid: {error}"
                )
            }
            Self::BuildProfile(error) => {
                write!(
                    formatter,
                    "Verilog-A worker build profile is invalid: {error}"
                )
            }
            Self::ModuleSelection => {
                formatter.write_str("Verilog-A worker module selection is invalid.")
            }
        }
    }
}

impl std::error::Error for WorkerCompileRequestError {}

/// A host explicitly selects whether to attempt the optional browser backend.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WorkerCompileTarget {
    Bytecode,
    #[cfg(feature = "wasm-jit")]
    WasmJit,
}

/// A successful compiler report and the optional secondary backend outcome.
/// A JIT refusal retains the report and its bytecode fallback.
#[derive(Debug)]
pub struct CompiledWorkerSource {
    pub report: Box<RuntimeCompileReport>,
    #[cfg(feature = "wasm-jit")]
    pub wasm_jit: Option<
        Result<
            rspice_veriloga::wasm_jit::WasmJitModelArtifact,
            rspice_veriloga::wasm_jit::WasmJitError,
        >,
    >,
}

/// Borrows one validated source closure and its exact module selection.
/// Transport identity and publication currentness remain host responsibilities.
#[derive(Debug)]
pub struct WorkerCompileRequest<'a> {
    bundle: &'a ProjectSourceBundle,
    selected_module: Option<&'a str>,
}

impl<'a> WorkerCompileRequest<'a> {
    pub fn try_new(
        bundle: &'a ProjectSourceBundle,
        selected_module: Option<&'a str>,
    ) -> Result<Self, WorkerCompileRequestError> {
        if bundle.language() != ProjectSourceLanguage::VerilogA {
            return Err(WorkerCompileRequestError::Language);
        }
        bundle
            .validate()
            .map_err(WorkerCompileRequestError::SourceBundle)?;
        build_profile::resolve_veriloga_build_profile(bundle)
            .map_err(WorkerCompileRequestError::BuildProfile)?;
        if selected_module.is_some_and(|module| {
            module.is_empty()
                || module.len() > MAX_PROJECT_SOURCE_LOGICAL_PATH_BYTES
                || module.chars().any(char::is_control)
        }) {
            return Err(WorkerCompileRequestError::ModuleSelection);
        }
        Ok(Self {
            bundle,
            selected_module,
        })
    }

    pub fn compile(
        self,
        target: WorkerCompileTarget,
    ) -> Result<CompiledWorkerSource, ProjectVerilogACompileError> {
        let report = compile_project_bundle_source(self.bundle, self.selected_module)?;
        Ok(match target {
            WorkerCompileTarget::Bytecode => CompiledWorkerSource {
                report,
                #[cfg(feature = "wasm-jit")]
                wasm_jit: None,
            },
            #[cfg(feature = "wasm-jit")]
            WorkerCompileTarget::WasmJit => {
                let wasm_jit = rspice_veriloga::wasm_jit::compile_model_value_module(
                    &report.model,
                    &report.canonical_ir,
                );
                CompiledWorkerSource {
                    report,
                    wasm_jit: Some(wasm_jit),
                }
            }
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rspice_design::project_sources::ProjectSourceOwner;

    const SOURCE: &str =
        "module worker(p, n); inout p, n; electrical p, n; analog I(p,n) <+ V(p,n); endmodule\n";

    fn bundle(language: ProjectSourceLanguage, source: &str) -> ProjectSourceBundle {
        ProjectSourceBundle::try_new(
            ProjectSourceOwner::code_workspace(language),
            language,
            format!("worker{}", language.required_extension()),
            source,
            [],
            [],
        )
        .unwrap()
    }

    #[test]
    fn source_admission_precedes_compilation_and_bytecode_needs_no_jit() {
        let foreign = bundle(ProjectSourceLanguage::RSpiceAutomation, "workflow: test");
        assert!(matches!(
            WorkerCompileRequest::try_new(&foreign, Some("worker")),
            Err(WorkerCompileRequestError::Language)
        ));
        let source = bundle(ProjectSourceLanguage::VerilogA, SOURCE);
        for module in [
            "",
            "worker\n",
            &"x".repeat(MAX_PROJECT_SOURCE_LOGICAL_PATH_BYTES + 1),
        ] {
            assert!(matches!(
                WorkerCompileRequest::try_new(&source, Some(module)),
                Err(WorkerCompileRequestError::ModuleSelection)
            ));
        }
        let compiled = WorkerCompileRequest::try_new(&source, Some("worker"))
            .unwrap()
            .compile(WorkerCompileTarget::Bytecode)
            .unwrap();
        assert_eq!(compiled.report.abi.module_name.as_str(), "worker");
        compiled.report.validate_integrity().unwrap();
        #[cfg(feature = "wasm-jit")]
        assert!(compiled.wasm_jit.is_none());
    }

    #[cfg(feature = "wasm-jit")]
    #[test]
    fn jit_compilation_retains_the_report_and_source_failures_stay_diagnosed() {
        let source = bundle(ProjectSourceLanguage::VerilogA, SOURCE);
        let compiled = WorkerCompileRequest::try_new(&source, Some("worker"))
            .unwrap()
            .compile(WorkerCompileTarget::WasmJit)
            .unwrap();
        compiled.report.validate_integrity().unwrap();
        let artifact = compiled.wasm_jit.unwrap().unwrap();
        assert!(!artifact.module().bytes().is_empty());

        let invalid = bundle(
            ProjectSourceLanguage::VerilogA,
            "module worker(p, n); inout p, n; electrical p, n; analog I(p,n) <+ @; endmodule\n",
        );
        let failure = WorkerCompileRequest::try_new(&invalid, Some("worker"))
            .unwrap()
            .compile(WorkerCompileTarget::WasmJit)
            .unwrap_err();
        let ProjectVerilogACompileError::Virtual(failure) = failure else {
            panic!("selected-module compilation must retain virtual source diagnostics");
        };
        assert!(failure.diagnostics.iter().any(|diagnostic| {
            diagnostic.logical_path.as_deref() == Some("worker.va")
                && diagnostic.byte_start.is_some()
                && diagnostic.byte_end.is_some()
        }));
    }

    #[cfg(feature = "wasm-jit")]
    use crate::{
        project_veriloga::project_virtual_compile_limits, veriloga::PreparedVerilogARuntime,
    };

    #[cfg(feature = "wasm-jit")]
    const BOUND_STEP_SOURCE: &str = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/bound_step.va"
    ));

    #[cfg(feature = "wasm-jit")]
    const INFINITE_CONSTANT_SOURCE: &str = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/infinite_constant.va"
    ));

    #[cfg(feature = "wasm-jit")]
    /// Compile one fixture source and seal it exactly as a project source is
    /// sealed. `try_from_virtual_compilation` is the constructor both the
    /// project and the signed-PDK paths reach, so a fixture that seals here
    /// seals in production.
    fn seal_runtime(file: &str, module: &str, source: &str) -> PreparedVerilogARuntime {
        let bundle = rspice_veriloga::VirtualSourceBundle::new(
            file,
            [rspice_veriloga::VirtualSourceFile::new(file, source)],
        )
        .expect("fixture bundle is well formed");
        let compilation = rspice_veriloga::VerilogACompiler::default()
            .compile_virtual_runtime(&bundle, module, project_virtual_compile_limits())
            .expect("fixture module compiles");
        PreparedVerilogARuntime::try_from_virtual_compilation(
            format!("__rspice_project__/fixture/{file}"),
            rspice_app_types::product::ContentDigest::from_bytes([0x5a; 32]),
            module.to_owned(),
            &compilation,
        )
        .expect("fixture compilation seals into a prepared runtime")
    }

    /// A module whose assignment pass has no steps exports no kernel for it,
    /// so `WasmJitModelArtifact::assignment_export` is `None` and the shared
    /// `WasmJitExecutable::run_assignments` — the same driver the browser
    /// device runs — returns `Ok` without dispatching anything. That artifact
    /// is whole and shippable, so the wire has to carry the absence: a
    /// defaulted name would announce an export the module does not have, and
    /// the worker would refuse to install a model that is perfectly valid.
    #[cfg(feature = "wasm-jit")]
    #[test]
    fn an_assignment_free_module_crosses_the_worker_wire_without_an_export() {
        const NO_ASSIGNMENTS: &str = r#"
`include "disciplines.vams"
module rspice_no_assignment_probe(p, n);
  inout p, n;
  electrical p, n;
  parameter real conductance = 0.5;
  analog I(p, n) <+ conductance * V(p, n);
endmodule
"#;
        // The control retains an assignment kernel through the same wire conversion.
        const ONE_ASSIGNMENT: &str = r#"
`include "disciplines.vams"
module rspice_one_assignment_probe(p, n);
  inout p, n;
  electrical p, n;
  parameter real conductance = 0.5;
  analog begin
    $discontinuity(0);
    I(p, n) <+ conductance * V(p, n);
  end
endmodule
"#;

        let empty = seal_runtime(
            "no-assignment.va",
            "rspice_no_assignment_probe",
            NO_ASSIGNMENTS,
        )
        .compile_wasm_jit_artifact()
        .expect("assignment-free module qualifies for the browser JIT");
        let empty = super::WasmJitWorkerArtifact::from_compiled(&empty);
        assert_eq!(
            empty.assignment_export, None,
            "a pass with no steps must cross the wire as an absence"
        );

        let control = seal_runtime(
            "one-assignment.va",
            "rspice_one_assignment_probe",
            ONE_ASSIGNMENT,
        )
        .compile_wasm_jit_artifact()
        .expect("single-assignment module qualifies for the browser JIT");
        let control = super::WasmJitWorkerArtifact::from_compiled(&control);
        assert_eq!(
            control.assignment_export.as_deref(),
            Some("rspice_wasm_jit_assign"),
            "a pass with steps still names its kernel on the wire"
        );

        // The absence has to survive the transport encoding as well, because
        // the worker protocol decodes this struct under `deny_unknown_fields`.
        let encoded = serde_json::to_string(&empty).expect("worker artifact encodes");
        let decoded: super::WasmJitWorkerArtifact =
            serde_json::from_str(&encoded).expect("worker artifact decodes");
        assert_eq!(decoded.assignment_export, None);
    }

    /// The reason the seal has to carry a non-finite float at all: this is the
    /// production browser entry point, and it opens by decoding the sealed
    /// model and canonical IR. A `$bound_step` module could not get past that
    /// decode, so no shipped model that bounds its own transient step reached
    /// the browser. `$bound_step` also roots the assignment pass, so the
    /// artifact it produces names a kernel — the same control the
    /// assignment-export test needed `$discontinuity` for, now available from
    /// the operator that actually motivated this.
    #[cfg(feature = "wasm-jit")]
    #[test]
    fn a_bound_step_module_compiles_all_the_way_to_a_browser_worker_artifact() {
        let artifact = seal_runtime(
            "bound-step.va",
            "rspice_bound_step_probe",
            BOUND_STEP_SOURCE,
        )
        .compile_wasm_jit_artifact()
        .expect("a $bound_step module qualifies for the browser JIT");
        let artifact = super::WasmJitWorkerArtifact::from_compiled(&artifact);
        assert_eq!(
            artifact.assignment_export.as_deref(),
            Some("rspice_wasm_jit_assign"),
            "$bound_step roots an assignment pass, so the artifact names its kernel"
        );
        assert!(
            !artifact.module_bytes.is_empty(),
            "the browser is handed a module, not an empty artifact"
        );
    }

    /// The same for the infinite parameter default, whose loss was silent in
    /// the canonical IR rather than loud: the browser JIT lowers that payload,
    /// so it used to be handed a model whose default had quietly become absent.
    #[cfg(feature = "wasm-jit")]
    #[test]
    fn an_infinite_folded_constant_reaches_the_browser_worker_artifact_intact() {
        let runtime = seal_runtime(
            "infinite-constant.va",
            "rspice_infinite_constant_probe",
            INFINITE_CONSTANT_SOURCE,
        );
        runtime
            .compile_wasm_jit_artifact()
            .expect("a module with an infinite default qualifies for the browser JIT");
        let ir: rspice_veriloga::canonical_ir::CanonicalIrArtifact = serde_json::from_str(
            serde_json::to_value(&runtime).unwrap()["canonical_ir_json"]
                .as_str()
                .unwrap(),
        )
        .expect("sealed IR payload parses");
        assert_eq!(
            ir.hir
                .parameters
                .iter()
                .find(|parameter| parameter.name.as_str() == "folded")
                .and_then(|parameter| parameter.default)
                .map(f64::to_bits),
            Some(f64::INFINITY.to_bits()),
            "the default the browser device elaborates from must be the declared one"
        );
    }
}
